1	package contractsentinel
2	
3	import (
4		"encoding/json"
5		"strings"
6		"testing"
7	)
8	
9	func mustConfig(t *testing.T, src string) *Config {
10		t.Helper()
11		cfg, f := ParseConfig([]byte(src))
12		if f != nil {
13			t.Fatalf("unexpected config failure: %+v", f)
14		}
15		return cfg
16	}
17	
18	func resolveJSON(t *testing.T, cfg *Config, reqSrc string) *Resolution {
19		t.Helper()
20		req, f := ParseRequest([]byte(reqSrc))
21		if f != nil {
22			t.Fatalf("unexpected request failure: %+v", f)
23		}
24		res, rf := Resolve(cfg, req)
25		if rf != nil {
26			t.Fatalf("unexpected resolve failure: %+v", rf)
27		}
28		return res
29	}
30	
31	const sampleConfig = `{
32	  "routes": [
33	    {"id": "api",    "methods": ["GET"],        "pathPrefix": "/api",         "upstream": "http://api.internal/v1"},
34	    {"id": "api-v2", "methods": ["*"],          "pathPrefix": "/api/v2",      "upstream": "https://api.internal:8443/v2"},
35	    {"id": "orders", "methods": ["GET", "POST"],"pathPrefix": "/api/orders", "upstream": "http://orders.internal"},
36	    {"id": "root",   "methods": ["*"],          "pathPrefix": "/",            "upstream": "https://fallback.internal/base/"},
37	    {"id": "users",  "methods": ["GET"],        "pathPrefix": "/users",       "upstream": "http://users.internal/u"}
38	  ]
39	}`
40	
41	func TestResolveBasicMatchAndJoin(t *testing.T) {
42		cfg := mustConfig(t, sampleConfig)
43	
44		cases := []struct {
45			name     string
46			request  string
47			routeID  string
48			upstream string
49		}{
50			{
51				name:     "exact prefix strips and joins base path",
52				request:  `{"method":"GET","target":"/api"}`,
53				routeID:  "api",
54				upstream: "http://api.internal/v1/",
55			},
56			{
57				name:     "prefix with deeper path joins on one slash",
58				request:  `{"method":"GET","target":"/api/orders/42"}`,
59				routeID:  "orders",
60				upstream: "http://orders.internal/42",
61			},
62			{
63				name:     "post also matches concrete method list",
64				request:  `{"method":"POST","target":"/api/orders"}`,
65				routeID:  "orders",
66				upstream: "http://orders.internal/",
67			},
68			{
69				name:     "longest prefix beats shorter on shared path",
70				request:  `{"method":"GET","target":"/api/orders"}`,
71				routeID:  "orders",
72				upstream: "http://orders.internal/",
73			},
74			{
75				name:     "upstream trailing base slash collapses to one",
76				request:  `{"method":"GET","target":"/users/7/profile"}`,
77				routeID:  "users",
78				upstream: "http://users.internal/u/7/profile",
79			},
80			{
81				name:     "root fallback keeps the full path",
82				request:  `{"method":"GET","target":"/healthz"}`,
83				routeID:  "root",
84				upstream: "https://fallback.internal/base/healthz",
85			},
86			{
87				name:     "root prefix with root target keeps junction slash",
88				request:  `{"method":"GET","target":"/"}`,
89				routeID:  "root",
90				upstream: "https://fallback.internal/base/",
91			},
92			{
93				name:     "wildcard method accepts unusual but legal method",
94				request:  `{"method":"PROPFIND","target":"/api/v2/things/9"}`,
95				routeID:  "api-v2",
96				upstream: "https://api.internal:8443/v2/things/9",
97			},
98			{
99				name:     "query string is ignored for matching but preserved verbatim",
100				request:  `{"method":"GET","target":"/api/orders/1?expand=items&a=&a=2&b=%41%2f"}`,
101				routeID:  "orders",
102				upstream: "http://orders.internal/1?expand=items&a=&a=2&b=%41%2f",
103			},
104			{
105				name:     "empty query string stays empty",
106				request:  `{"method":"GET","target":"/api?"}`,
107				routeID:  "api",
108				upstream: "http://api.internal/v1/?",
109			},
110			{
111				name:     "encoded path is matched raw and kept raw",
112				request:  `{"method":"GET","target":"/users/a%20b%2Fc"}`,
113				routeID:  "users",
114				upstream: "http://users.internal/u/a%20b%2Fc",
115			},
116		}
117		for _, tc := range cases {
118			t.Run(tc.name, func(t *testing.T) {
119				res := resolveJSON(t, cfg, tc.request)
120				if res.RouteID != tc.routeID {
121					t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
122				}
123				if res.UpstreamURL != tc.upstream {
124					t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
125				}
126			})
127		}
128	}
