142		// "%2F" is an encoded slash in the remainder, never a segment separator.
143		res = resolveJSON(t, cfg, `{"method":"GET","target":"/api%2Fv2/secret"}`)
144		if res.RouteID != "root" {
145			t.Fatalf("routeId = %q, want root (encoded slash is not a boundary)", res.RouteID)
