261	func TestInvalidConfig(t *testing.T) {
262		cases := []struct {
263			name    string
264			src     string
265			want    string // reason substring
266			located bool   // whether the reason should locate the route
267		}{
268			{"not json", `{not json`, "not valid JSON", false},
269			{"empty id", `{"routes":[{"id":"","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`, "id must be non-empty", true},
270			{"duplicate id", `{"routes":[
271			  {"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h1"},
272			  {"id":"x","methods":["GET"],"pathPrefix":"/b","upstream":"http://h2"}]}`, "duplicate id", true},
273			{"empty methods", `{"routes":[{"id":"x","methods":[],"pathPrefix":"/a","upstream":"http://h"}]}`, "non-empty", true},
274			{"bad method token", `{"routes":[{"id":"x","methods":["GE T"],"pathPrefix":"/a","upstream":"http://h"}]}`, "invalid method", true},
275			{"prefix not absolute", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"a","upstream":"http://h"}]}`, "start with /", true},
276			{"prefix trailing slash", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a/","upstream":"http://h"}]}`, "end with /", true},
277			{"root trailing slash allowed", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/","upstream":"http://h"}]}`, "", true},
278			{"prefix with query", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a?x=1","upstream":"http://h"}]}`, "query string or fragment", true},
279			{"prefix with fragment", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a#f","upstream":"http://h"}]}`, "query string or fragment", true},
280			{"prefix bad percent escape", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a%2","upstream":"http://h"}]}`, "percent escape", true},
281			{"upstream relative", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"/path"}]}`, "absolute http or https", true},
282			{"upstream wrong scheme", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"ftp://h"}]}`, "absolute http or https", true},
283			{"upstream missing host", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http:///path"}]}`, "include a host", true},
284			{"upstream with query", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h?x=1"}]}`, "query string or fragment", true},
285			{"upstream with fragment", `{"routes":[{"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h#f"}]}`, "query string or fragment", true},
286		}
287		for _, tc := range cases {
288			t.Run(tc.name, func(t *testing.T) {
289				_, f := ParseConfig([]byte(tc.src))
290				if tc.want == "" {
291					if f != nil {
292						t.Fatalf("unexpected failure: %+v", f)
293					}
294					return
295				}
296				if f == nil {
297					t.Fatalf("expected invalid_config containing %q", tc.want)
298				}
299				if f.Code != "invalid_config" {
300					t.Fatalf("code = %q, want invalid_config", f.Code)
301				}
302				if !strings.Contains(f.Reason, tc.want) {
303					t.Fatalf("reason = %q, want substring %q", f.Reason, tc.want)
304				}
305				if tc.located && !strings.Contains(f.Reason, "route ") {
306					t.Fatalf("reason = %q should locate the route", f.Reason)
307				}
308			})
309		}
310	}
