312	func TestInvalidConfigFieldTypes(t *testing.T) {
313		// Unlike TestInvalidConfig's missing/illegal-value cases, these exercise
314		// fields whose JSON type itself is wrong: valid JSON that cannot satisfy
315		// the field's type must still be invalid_config, but the reason has to
316		// name the route position (and a valid string id), distinguish it from a
317		// JSON syntax failure, and say why the field could not be read.
318		goodRoute := `"id":"x","methods":["GET"],"pathPrefix":"/a","upstream":"http://h"`
319	
320		cases := []struct {
321			name      string
322			src       string
323			want      []string // all must appear in the reason
324			forbidden []string // none may appear in the reason
325		}{
326			{
327				name: "methods string on second route, id after the bad field",
328				src: `{"routes":[
329				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
330				  {"methods":"GET","id":"orders","pathPrefix":"/api/orders","upstream":"http://o"}
331				]}`,
332				want: []string{"route 2", `"orders"`, "methods must be an array"},
333			},
334			{
335				name: "methods null",
336				src:  `{"routes":[{` + goodRoute + `,"methods":null}]}`,
337				want: []string{"route 1", `"x"`, "methods must be an array"},
338			},
339			{
340				name: "methods is an object",
341				src:  `{"routes":[{` + goodRoute + `,"methods":{"GET":true}}]}`,
342				want: []string{"route 1", `"x"`, "methods must be an array"},
343			},
344			{
345				name: "numeric entry inside a legal methods array",
346				src: `{"routes":[
347				  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://a"},
348				  {"id":"orders","methods":["GET",1],"pathPrefix":"/api/orders","upstream":"http://o"}
349				]}`,
350				want: []string{"route 2", `"orders"`, "methods entry 2 must be a string"},
351			},
352			{
353				name: "null entry inside methods",
354				src:  `{"routes":[{` + goodRoute + `,"methods":[null]}]}`,
355				want: []string{"route 1", "methods entry 1 must be a string"},
356			},
357			{
358				name:      "id is a number",
359				src:       `{"routes":[{"id":1,"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
360				want:      []string{"route 1", "id must be a string"},
361				forbidden: []string{"(id "},
362			},
363			{
364				name:      "id is an object",
365				src:       `{"routes":[{"id":{"v":1},"methods":["GET"],"pathPrefix":"/a","upstream":"http://h"}]}`,
366				want:      []string{"route 1", "id must be a string"},
367				forbidden: []string{"(id "},
368			},
369			{
370				name: "pathPrefix is a number, id written after it",
371				src:  `{"routes":[{"methods":["GET"],"pathPrefix":1,"id":"orders","upstream":"http://o"}]}`,
372				want: []string{"route 1", `"orders"`, "pathPrefix must be a string"},
373			},
374			{
375				name: "upstream is a boolean, id written after it",
376				src:  `{"routes":[{"methods":["GET"],"pathPrefix":"/a","upstream":true,"id":"orders"}]}`,
377				want: []string{"route 1", `"orders"`, "upstream must be a string"},
378			},
379			{
380				name: "routes entry is not an object",
381				src:  `{"routes":[42]}`,
382				want: []string{"route 1", "route entry must be a JSON object"},
383			},
384		}
385		for _, tc := range cases {
386			t.Run(tc.name, func(t *testing.T) {
387				_, f := ParseConfig([]byte(tc.src))
388				if f == nil {
389					t.Fatalf("expected invalid_config")
390				}
391				if f.Code != "invalid_config" {
392					t.Fatalf("code = %q, want invalid_config", f.Code)
393				}
394				if strings.Contains(f.Reason, "not valid JSON") {
395					t.Fatalf("field type error must not be described as a JSON syntax failure: %q", f.Reason)
396				}
397				for _, want := range tc.want {
398					if !strings.Contains(f.Reason, want) {
399						t.Fatalf("reason = %q, want substring %q", f.Reason, want)
400					}
401				}
402				for _, bad := range tc.forbidden {
403					if strings.Contains(f.Reason, bad) {
404						t.Fatalf("reason = %q must not contain %q", f.Reason, bad)
405					}
406				}
407			})
408		}
409	
410		// Broken JSON syntax stays a parse failure and never gets a guessed
411		// route position, even when the corruption is inside the routes array.
412		for _, src := range []string{`{not json`, `{"routes": [{"id":"x"} broken`} {
413			_, f := ParseConfig([]byte(src))
414			if f == nil || f.Code != "invalid_config" {
415				t.Fatalf("got %+v, want invalid_config for %q", f, src)
416			}
417			if !strings.Contains(f.Reason, "not valid JSON") {
418				t.Fatalf("reason = %q, want a JSON parse failure", f.Reason)
419			}
420			if strings.Contains(f.Reason, "route 1") {
421				t.Fatalf("syntax failure must not guess a route position: %q", f.Reason)
422			}
423		}
424	
425		// Fixing the second route's methods lets the request resolve normally,
426		// including through the first route it originally matched.
427		cfg := mustConfig(t, `{"routes":[
428		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
429		  {"id":"orders","methods":["GET"],"pathPrefix":"/api/orders","upstream":"http://orders.internal"}
430		]}`)
431		res := resolveJSON(t, cfg, `{"method":"GET","target":"/api/items"}`)
432		if res.RouteID != "api" || res.UpstreamURL != "http://api.internal/v1/items" {
433			t.Fatalf("got %+v, want api / http://api.internal/v1/items", res)
434		}
435	}
